const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const db = require('../db');

const app = express();
app.use(express.json());

const WASM_MODULES_DIR = path.resolve(__dirname, '../wasm_binaries');
const ASSETS_DIR = path.resolve(__dirname, '../tenant_assets');

app.post('/api/wasm/process-media', async (req, res) => {
  const { wasmModuleId, assetId } = req.body;

  // Validate that the requested asset is owned by the authenticated tenant
  const assetRecord = await db('tenant_assets')
    .where({ id: assetId, tenant_id: req.user.tenantId })
    .first();
  if (!assetRecord) {
    return res.status(404).json({ error: 'Asset not found or access denied' });
  }

  const assetPath = path.join(ASSETS_DIR, `${assetId}.raw`);
  const wasmPath = path.join(WASM_MODULES_DIR, `${wasmModuleId}.wasm`);

  try {
    const [wasmBytes, assetBytes] = await Promise.all([
      fs.readFile(wasmPath),
      fs.readFile(assetPath)
    ]);

    const wasmModule = await WebAssembly.instantiate(wasmBytes, {});
    const { memory, transform_buffer } = wasmModule.instance.exports;

    const memoryView = new Uint8Array(memory.buffer, 0, assetBytes.length);
    memoryView.set(assetBytes);
    transform_buffer(assetBytes.length);

    const outputBuffer = Buffer.from(memory.buffer, 0, assetBytes.length);
    res.setHeader('Content-Type', 'application/octet-stream');
    return res.send(outputBuffer);
  } catch (err) {
    return res.status(500).json({ error: 'WASM media transformation failed' });
  }
});

module.exports = app;
